DDL = "\nCREATE TABLE cehub_product.research_measurement_workpacks (\n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tmarket_space_id UUID NOT NULL, \n\tproduct_line_id UUID, \n\tscope_key UUID NOT NULL, \n\tstudy_id UUID NOT NULL, \n\tsubject_kind VARCHAR(24) NOT NULL, \n\tsubject_id UUID NOT NULL, \n\tsubject_series_id UUID NOT NULL, \n\tresearch_task_id UUID, \n\tscoped_work_item_id UUID, \n\topportunity_id UUID, \n\tstrategy_id UUID, \n\tdefinition_id UUID, \n\tmode VARCHAR(24) NOT NULL, \n\tcreator_user_id UUID NOT NULL, \n\tdeliverer_user_id UUID NOT NULL, \n\treceiver_user_id UUID NOT NULL, \n\tbody JSONB NOT NULL, \n\tsource_snapshot JSONB NOT NULL, \n\trequest_id UUID NOT NULL, \n\trequest_digest VARCHAR(64) NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tCONSTRAINT pk_research_measurement_workpacks PRIMARY KEY (id), \n\tCONSTRAINT fk_research_measurement_workpacks_space FOREIGN KEY(tenant_id, market_space_id) REFERENCES cehub_product.market_spaces (tenant_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_research_measurement_workpacks_line FOREIGN KEY(tenant_id, market_space_id, product_line_id) REFERENCES cehub_product.product_nodes (tenant_id, market_space_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT ck_research_measurement_workpacks_scope_key CHECK (scope_key=coalesce(product_line_id,market_space_id)), \n\tCONSTRAINT fk_research_pack_study FOREIGN KEY(tenant_id, market_space_id, scope_key, study_id) REFERENCES cehub_product.research_measurement_studies (tenant_id, market_space_id, scope_key, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_research_pack_research_task FOREIGN KEY(tenant_id, market_space_id, research_task_id) REFERENCES cehub_product.research_tasks (tenant_id, market_space_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_research_pack_scoped_work_item FOREIGN KEY(tenant_id, market_space_id, scoped_work_item_id) REFERENCES cehub_project.scoped_work_items (tenant_id, market_space_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_research_pack_opportunity FOREIGN KEY(tenant_id, market_space_id, opportunity_id) REFERENCES cehub_product.opportunities (tenant_id, market_space_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_research_pack_strategy FOREIGN KEY(tenant_id, market_space_id, strategy_id) REFERENCES cehub_product.product_strategies (tenant_id, market_space_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_research_pack_definition FOREIGN KEY(tenant_id, market_space_id, definition_id) REFERENCES cehub_product.product_definitions (tenant_id, market_space_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT ck_research_measurement_workpacks_actual_subject_fk CHECK (subject_kind IN ('research_task','scoped_work_item','opportunity','strategy','definition') AND num_nonnulls(research_task_id,scoped_work_item_id,opportunity_id,strategy_id,definition_id)=1 AND ((subject_kind='research_task' AND subject_id=research_task_id) OR (subject_kind='scoped_work_item' AND subject_id=scoped_work_item_id) OR (subject_kind='opportunity' AND subject_id=opportunity_id) OR (subject_kind='strategy' AND subject_id=strategy_id) OR (subject_kind='definition' AND subject_id=definition_id)) IS TRUE), \n\tCONSTRAINT fk_research_pack_creator_user_id FOREIGN KEY(tenant_id, creator_user_id) REFERENCES cehub_core.users (tenant_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_research_pack_deliverer_user_id FOREIGN KEY(tenant_id, deliverer_user_id) REFERENCES cehub_core.users (tenant_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_research_pack_receiver_user_id FOREIGN KEY(tenant_id, receiver_user_id) REFERENCES cehub_core.users (tenant_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT uq_research_pack_scope UNIQUE (tenant_id, market_space_id, scope_key, id), \n\tCONSTRAINT uq_research_pack_study_scope UNIQUE (tenant_id, market_space_id, scope_key, study_id, id), \n\tCONSTRAINT uq_research_pack_subject_mode UNIQUE (tenant_id, study_id, subject_kind, subject_series_id, mode), \n\tCONSTRAINT uq_research_pack_request UNIQUE (tenant_id, creator_user_id, request_id), \n\tCONSTRAINT ck_research_measurement_workpacks_independent_roles CHECK (deliverer_user_id<>receiver_user_id AND mode IN ('baseline_without_ai','assisted')), \n\tCONSTRAINT ck_research_measurement_workpacks_scope_shape CHECK (jsonb_typeof(body)='object' AND jsonb_typeof(source_snapshot)='object' AND body->>'full_roster_confirmed'='true' AND request_digest ~ '^[a-f0-9]{64}$')\n)\n\n;\nCREATE INDEX ix_research_pack_scope_study ON cehub_product.research_measurement_workpacks (tenant_id, market_space_id, scope_key, study_id, id);\n\nCREATE TABLE cehub_product.research_measurement_workpack_members (\n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tmarket_space_id UUID NOT NULL, \n\tproduct_line_id UUID, \n\tscope_key UUID NOT NULL, \n\tworkpack_id UUID NOT NULL, \n\tuser_id UUID NOT NULL, \n\trole_id VARCHAR(128) NOT NULL, \n\tfirst_use BOOLEAN NOT NULL, \n\tCONSTRAINT pk_research_measurement_workpack_members PRIMARY KEY (id), \n\tCONSTRAINT fk_research_measurement_workpack_members_space FOREIGN KEY(tenant_id, market_space_id) REFERENCES cehub_product.market_spaces (tenant_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_research_measurement_workpack_members_line FOREIGN KEY(tenant_id, market_space_id, product_line_id) REFERENCES cehub_product.product_nodes (tenant_id, market_space_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT ck_research_measurement_workpack_members_scope_key CHECK (scope_key=coalesce(product_line_id,market_space_id)), \n\tCONSTRAINT fk_research_pack_member_pack FOREIGN KEY(tenant_id, market_space_id, scope_key, workpack_id) REFERENCES cehub_product.research_measurement_workpacks (tenant_id, market_space_id, scope_key, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_research_pack_member_user FOREIGN KEY(tenant_id, user_id) REFERENCES cehub_core.users (tenant_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT uq_research_pack_member UNIQUE (tenant_id, market_space_id, scope_key, workpack_id, user_id), \n\tCONSTRAINT ck_research_measurement_workpack_members_role_nonblank CHECK (btrim(role_id)<>'')\n)\n\n;\n\n\nCREATE TABLE cehub_product.research_measurement_deliveries (\n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tmarket_space_id UUID NOT NULL, \n\tproduct_line_id UUID, \n\tscope_key UUID NOT NULL, \n\tstudy_id UUID NOT NULL, \n\tworkpack_id UUID NOT NULL, \n\tround INTEGER NOT NULL, \n\tactor_user_id UUID NOT NULL, \n\treceiver_user_id UUID NOT NULL, \n\tdeliverer_consent_id UUID NOT NULL, \n\treceiver_consent_id UUID NOT NULL, \n\tsubject_kind VARCHAR(24) NOT NULL, \n\tsubject_id UUID NOT NULL, \n\tsubject_series_id UUID NOT NULL, \n\tresearch_task_id UUID, \n\tscoped_work_item_id UUID, \n\topportunity_id UUID, \n\tstrategy_id UUID, \n\tdefinition_id UUID, \n\tlocator TEXT NOT NULL, \n\tdescription TEXT NOT NULL, \n\tsource_snapshot JSONB NOT NULL, \n\tsource_digest VARCHAR(64) NOT NULL, \n\trequest_id UUID NOT NULL, \n\trequest_digest VARCHAR(64) NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tCONSTRAINT pk_research_measurement_deliveries PRIMARY KEY (id), \n\tCONSTRAINT fk_research_measurement_deliveries_space FOREIGN KEY(tenant_id, market_space_id) REFERENCES cehub_product.market_spaces (tenant_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_research_measurement_deliveries_line FOREIGN KEY(tenant_id, market_space_id, product_line_id) REFERENCES cehub_product.product_nodes (tenant_id, market_space_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT ck_research_measurement_deliveries_scope_key CHECK (scope_key=coalesce(product_line_id,market_space_id)), \n\tCONSTRAINT fk_research_delivery_pack FOREIGN KEY(tenant_id, market_space_id, scope_key, study_id, workpack_id) REFERENCES cehub_product.research_measurement_workpacks (tenant_id, market_space_id, scope_key, study_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_research_delivery_research_task FOREIGN KEY(tenant_id, market_space_id, research_task_id) REFERENCES cehub_product.research_tasks (tenant_id, market_space_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_research_delivery_scoped_work_item FOREIGN KEY(tenant_id, market_space_id, scoped_work_item_id) REFERENCES cehub_project.scoped_work_items (tenant_id, market_space_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_research_delivery_opportunity FOREIGN KEY(tenant_id, market_space_id, opportunity_id) REFERENCES cehub_product.opportunities (tenant_id, market_space_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_research_delivery_strategy FOREIGN KEY(tenant_id, market_space_id, strategy_id) REFERENCES cehub_product.product_strategies (tenant_id, market_space_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_research_delivery_definition FOREIGN KEY(tenant_id, market_space_id, definition_id) REFERENCES cehub_product.product_definitions (tenant_id, market_space_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT ck_research_measurement_deliveries_actual_subject_fk CHECK (subject_kind IN ('research_task','scoped_work_item','opportunity','strategy','definition') AND num_nonnulls(research_task_id,scoped_work_item_id,opportunity_id,strategy_id,definition_id)=1 AND ((subject_kind='research_task' AND subject_id=research_task_id) OR (subject_kind='scoped_work_item' AND subject_id=scoped_work_item_id) OR (subject_kind='opportunity' AND subject_id=opportunity_id) OR (subject_kind='strategy' AND subject_id=strategy_id) OR (subject_kind='definition' AND subject_id=definition_id)) IS TRUE), \n\tCONSTRAINT fk_research_delivery_sender_consent FOREIGN KEY(tenant_id, market_space_id, scope_key, study_id, actor_user_id, deliverer_consent_id) REFERENCES cehub_product.research_measurement_consents (tenant_id, market_space_id, scope_key, study_id, participant_user_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_research_delivery_receiver_consent FOREIGN KEY(tenant_id, market_space_id, scope_key, study_id, receiver_user_id, receiver_consent_id) REFERENCES cehub_product.research_measurement_consents (tenant_id, market_space_id, scope_key, study_id, participant_user_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT uq_research_delivery_scope UNIQUE (tenant_id, market_space_id, scope_key, study_id, workpack_id, id), \n\tCONSTRAINT uq_research_delivery_round UNIQUE (tenant_id, market_space_id, scope_key, workpack_id, round), \n\tCONSTRAINT uq_research_delivery_request UNIQUE (tenant_id, actor_user_id, request_id), \n\tCONSTRAINT ck_research_measurement_deliveries_round_content CHECK (round>0 AND actor_user_id<>receiver_user_id AND btrim(locator)<>'' AND btrim(description)<>''), \n\tCONSTRAINT ck_research_measurement_deliveries_source_digests CHECK (source_digest ~ '^[a-f0-9]{64}$' AND request_digest ~ '^[a-f0-9]{64}$' AND jsonb_typeof(source_snapshot)='object')\n)\n\n;\n\n\nCREATE TABLE cehub_product.research_measurement_receptions (\n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tmarket_space_id UUID NOT NULL, \n\tproduct_line_id UUID, \n\tscope_key UUID NOT NULL, \n\tstudy_id UUID NOT NULL, \n\tworkpack_id UUID NOT NULL, \n\tdelivery_id UUID NOT NULL, \n\tactor_user_id UUID NOT NULL, \n\treceiver_consent_id UUID NOT NULL, \n\tdecision VARCHAR(16) NOT NULL, \n\tcriteria_checked BOOLEAN NOT NULL, \n\treason TEXT NOT NULL, \n\tsource_snapshot JSONB NOT NULL, \n\tsource_digest VARCHAR(64) NOT NULL, \n\trequest_id UUID NOT NULL, \n\trequest_digest VARCHAR(64) NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tCONSTRAINT pk_research_measurement_receptions PRIMARY KEY (id), \n\tCONSTRAINT fk_research_measurement_receptions_space FOREIGN KEY(tenant_id, market_space_id) REFERENCES cehub_product.market_spaces (tenant_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_research_measurement_receptions_line FOREIGN KEY(tenant_id, market_space_id, product_line_id) REFERENCES cehub_product.product_nodes (tenant_id, market_space_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT ck_research_measurement_receptions_scope_key CHECK (scope_key=coalesce(product_line_id,market_space_id)), \n\tCONSTRAINT fk_research_reception_delivery FOREIGN KEY(tenant_id, market_space_id, scope_key, study_id, workpack_id, delivery_id) REFERENCES cehub_product.research_measurement_deliveries (tenant_id, market_space_id, scope_key, study_id, workpack_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_research_reception_consent FOREIGN KEY(tenant_id, market_space_id, scope_key, study_id, actor_user_id, receiver_consent_id) REFERENCES cehub_product.research_measurement_consents (tenant_id, market_space_id, scope_key, study_id, participant_user_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT uq_research_reception_delivery UNIQUE (tenant_id, delivery_id), \n\tCONSTRAINT uq_research_reception_request UNIQUE (tenant_id, actor_user_id, request_id), \n\tCONSTRAINT ck_research_measurement_receptions_decision_content CHECK (decision IN ('accepted','returned') AND criteria_checked AND btrim(reason)<>''), \n\tCONSTRAINT ck_research_measurement_receptions_source_digests CHECK (source_digest ~ '^[a-f0-9]{64}$' AND request_digest ~ '^[a-f0-9]{64}$' AND jsonb_typeof(source_snapshot)='object')\n)\n\n;\nCREATE INDEX ix_research_reception_pack ON cehub_product.research_measurement_receptions (tenant_id, workpack_id);\n\nCREATE TABLE cehub_product.research_measurement_closures (\n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tmarket_space_id UUID NOT NULL, \n\tproduct_line_id UUID, \n\tscope_key UUID NOT NULL, \n\tworkpack_id UUID NOT NULL, \n\tactor_user_id UUID NOT NULL, \n\toutcome VARCHAR(16) NOT NULL, \n\treason TEXT NOT NULL, \n\trequest_id UUID NOT NULL, \n\trequest_digest VARCHAR(64) NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tCONSTRAINT pk_research_measurement_closures PRIMARY KEY (id), \n\tCONSTRAINT fk_research_measurement_closures_space FOREIGN KEY(tenant_id, market_space_id) REFERENCES cehub_product.market_spaces (tenant_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_research_measurement_closures_line FOREIGN KEY(tenant_id, market_space_id, product_line_id) REFERENCES cehub_product.product_nodes (tenant_id, market_space_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT ck_research_measurement_closures_scope_key CHECK (scope_key=coalesce(product_line_id,market_space_id)), \n\tCONSTRAINT fk_research_closure_pack FOREIGN KEY(tenant_id, market_space_id, scope_key, workpack_id) REFERENCES cehub_product.research_measurement_workpacks (tenant_id, market_space_id, scope_key, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_research_closure_actor FOREIGN KEY(tenant_id, actor_user_id) REFERENCES cehub_core.users (tenant_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT uq_research_closure_pack UNIQUE (tenant_id, market_space_id, scope_key, workpack_id), \n\tCONSTRAINT uq_research_closure_request UNIQUE (tenant_id, actor_user_id, request_id), \n\tCONSTRAINT ck_research_measurement_closures_closure_content CHECK (outcome IN ('failed','cancelled') AND btrim(reason)<>'' AND request_digest ~ '^[a-f0-9]{64}$')\n)\n\n;\n"

GUARDS = "CREATE FUNCTION cehub_product.guard_research_workpack() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$\nDECLARE s cehub_product.research_measurement_studies;\nDECLARE source_line uuid;\nDECLARE source_series uuid;\nDECLARE source_created timestamptz;\nBEGIN\n PERFORM 1 FROM cehub_product.market_spaces WHERE tenant_id=NEW.tenant_id AND id=NEW.market_space_id FOR UPDATE;\n SELECT * INTO s FROM cehub_product.research_measurement_studies WHERE tenant_id=NEW.tenant_id AND market_space_id=NEW.market_space_id AND id=NEW.study_id;\n IF s.id IS NULL OR s.scope_key IS DISTINCT FROM NEW.scope_key OR s.product_line_id IS DISTINCT FROM NEW.product_line_id OR NEW.created_at<s.created_at OR NEW.created_at>=s.window_end\n  OR NEW.body->>'study_id' IS DISTINCT FROM NEW.study_id::text\n  OR NEW.body->>'subject_kind' IS DISTINCT FROM NEW.subject_kind OR NEW.body->>'subject_id' IS DISTINCT FROM NEW.subject_id::text OR NEW.body->>'subject_series_id' IS DISTINCT FROM NEW.subject_series_id::text\n  OR NEW.body->>'mode' IS DISTINCT FROM NEW.mode\n  OR NEW.body->>'deliverer_user_id' IS DISTINCT FROM NEW.deliverer_user_id::text\n  OR NEW.body->>'receiver_user_id' IS DISTINCT FROM NEW.receiver_user_id::text\n  OR NEW.body->>'evidence_kind' IS DISTINCT FROM s.evidence_kind\n  OR NEW.body->>'scenario_id' IS DISTINCT FROM s.protocol->>'scenario_id'\n  OR NEW.body->>'full_roster_confirmed' IS DISTINCT FROM 'true'\n  OR NOT coalesce(s.protocol->'complexity_strata' ? (NEW.body->>'complexity_stratum'),false)\n  OR coalesce(btrim(NEW.body->>'workflow_version'),'')=''\n  OR coalesce(btrim(NEW.body->>'scope'),'')='' OR coalesce(btrim(NEW.body->>'completion_criteria'),'')=''\n  OR (NEW.body->>'pair_key' IS NULL)<>(NEW.body->>'matching_basis' IS NULL)\n THEN RAISE EXCEPTION 'Workpack must fix the registered study, scope and comparison identity'; END IF;\n IF jsonb_typeof(NEW.body->'members') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Workpack requires an explicit full roster'; END IF;\n IF jsonb_array_length(NEW.body->'members') NOT BETWEEN 2 AND 20\n  OR (SELECT count(DISTINCT x->>'user_id') FROM jsonb_array_elements(NEW.body->'members') x)<>jsonb_array_length(NEW.body->'members')\n  OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.body->'members') x WHERE x->>'user_id'=NEW.deliverer_user_id::text)\n  OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.body->'members') x WHERE x->>'user_id'=NEW.receiver_user_id::text)\n  OR EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.body->'members') x WHERE NOT coalesce(s.protocol->'role_ids' ? (x->>'role_id'),false) OR jsonb_typeof(x->'first_use') IS DISTINCT FROM 'boolean'\n   OR NOT EXISTS(SELECT 1 FROM cehub_product.market_space_members m JOIN cehub_core.users u ON u.tenant_id=m.tenant_id AND u.id=m.user_id WHERE m.tenant_id=NEW.tenant_id AND m.market_space_id=NEW.market_space_id AND m.user_id=(x->>'user_id')::uuid AND m.access IN ('contributor','manager') AND u.is_active)\n   OR (NEW.product_line_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM cehub_product.product_line_members l WHERE l.tenant_id=NEW.tenant_id AND l.product_line_id=NEW.product_line_id AND l.user_id=(x->>'user_id')::uuid AND l.access IN ('contributor','manager'))))\n THEN RAISE EXCEPTION 'Roster must name unique active actual project members, registered roles and independent receiver'; END IF;\n IF s.evidence_kind='real_business' AND (EXISTS(SELECT 1 FROM cehub_product.research_measurement_samples v WHERE v.tenant_id=NEW.tenant_id AND v.study_id=NEW.study_id AND v.subject_kind=NEW.subject_kind AND v.subject_series_id=NEW.subject_series_id) OR EXISTS(SELECT 1 FROM cehub_product.research_measurement_workpacks v WHERE v.tenant_id=NEW.tenant_id AND v.study_id=NEW.study_id AND v.subject_kind=NEW.subject_kind AND v.subject_series_id=NEW.subject_series_id))\n THEN RAISE EXCEPTION 'A real workpack must be registered before its participant observations'; END IF;\n\n IF NEW.subject_kind='research_task' THEN\n  SELECT product_line_id,id,created_at INTO source_line,source_series,source_created FROM cehub_product.research_tasks WHERE tenant_id=NEW.tenant_id AND market_space_id=NEW.market_space_id AND id=NEW.subject_id;\n ELSIF NEW.subject_kind='scoped_work_item' THEN\n  SELECT product_line_id,id,created_at INTO source_line,source_series,source_created FROM cehub_project.scoped_work_items WHERE tenant_id=NEW.tenant_id AND market_space_id=NEW.market_space_id AND id=NEW.subject_id;\n ELSIF NEW.subject_kind='opportunity' THEN\n  SELECT product_line_id,series_id,created_at INTO source_line,source_series,source_created FROM cehub_product.opportunities WHERE tenant_id=NEW.tenant_id AND market_space_id=NEW.market_space_id AND id=NEW.subject_id;\n ELSIF NEW.subject_kind='strategy' THEN\n  SELECT product_line_id,series_id,created_at INTO source_line,source_series,source_created FROM cehub_product.product_strategies WHERE tenant_id=NEW.tenant_id AND market_space_id=NEW.market_space_id AND id=NEW.subject_id;\n ELSIF NEW.subject_kind='definition' THEN\n  SELECT product_line_id,series_id,created_at INTO source_line,source_series,source_created FROM cehub_product.product_definitions WHERE tenant_id=NEW.tenant_id AND market_space_id=NEW.market_space_id AND id=NEW.subject_id;\n END IF;\n IF source_series IS NULL OR source_series IS DISTINCT FROM NEW.subject_series_id OR source_line IS DISTINCT FROM NEW.product_line_id OR source_created>NEW.created_at\n THEN RAISE EXCEPTION 'Research workpack must reference an actual version, stable series and exact registered scope'; END IF;\n RETURN NEW;\nEND $$;\nCREATE FUNCTION cehub_product.guard_research_workpack_roster() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$\nBEGIN\n IF (SELECT count(*) FROM cehub_product.research_measurement_workpack_members m WHERE m.tenant_id=NEW.tenant_id AND m.market_space_id=NEW.market_space_id AND m.workpack_id=NEW.id)<>jsonb_array_length(NEW.body->'members')\n THEN RAISE EXCEPTION 'Workpack and complete roster must be recorded together'; END IF;\n RETURN NEW;\nEND $$;\nCREATE FUNCTION cehub_product.guard_research_workpack_member() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$\nDECLARE p cehub_product.research_measurement_workpacks;\nBEGIN\n PERFORM 1 FROM cehub_product.market_spaces WHERE tenant_id=NEW.tenant_id AND id=NEW.market_space_id FOR UPDATE;\n SELECT * INTO p FROM cehub_product.research_measurement_workpacks WHERE tenant_id=NEW.tenant_id AND market_space_id=NEW.market_space_id AND id=NEW.workpack_id;\n IF p.id IS NULL OR p.scope_key IS DISTINCT FROM NEW.scope_key OR p.product_line_id IS DISTINCT FROM NEW.product_line_id OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p.body->'members') x WHERE x->>'user_id'=NEW.user_id::text AND x->>'role_id'=NEW.role_id AND (x->>'first_use')::boolean=NEW.first_use)\n THEN RAISE EXCEPTION 'Actual member row must match the immutable workpack roster'; END IF;\n RETURN NEW;\nEND $$;\nCREATE FUNCTION cehub_product.guard_research_delivery() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$\nDECLARE p cehub_product.research_measurement_workpacks;\nDECLARE s cehub_product.research_measurement_studies;\nDECLARE prev cehub_product.research_measurement_deliveries;\nDECLARE sender_grant cehub_product.research_measurement_consents;\nDECLARE receiver_grant cehub_product.research_measurement_consents;\nDECLARE source_line uuid;\nDECLARE source_series uuid;\nDECLARE source_created timestamptz;\nBEGIN\n PERFORM 1 FROM cehub_product.market_spaces WHERE tenant_id=NEW.tenant_id AND id=NEW.market_space_id FOR UPDATE;\n SELECT * INTO p FROM cehub_product.research_measurement_workpacks WHERE tenant_id=NEW.tenant_id AND market_space_id=NEW.market_space_id AND id=NEW.workpack_id;\n SELECT * INTO s FROM cehub_product.research_measurement_studies WHERE tenant_id=NEW.tenant_id AND market_space_id=NEW.market_space_id AND id=p.study_id;\n SELECT * INTO prev FROM cehub_product.research_measurement_deliveries WHERE tenant_id=NEW.tenant_id AND workpack_id=NEW.workpack_id ORDER BY round DESC LIMIT 1;\n SELECT * INTO sender_grant FROM cehub_product.research_measurement_consents WHERE tenant_id=NEW.tenant_id AND study_id=p.study_id AND participant_user_id=p.deliverer_user_id ORDER BY version DESC LIMIT 1;\n SELECT * INTO receiver_grant FROM cehub_product.research_measurement_consents WHERE tenant_id=NEW.tenant_id AND study_id=p.study_id AND participant_user_id=p.receiver_user_id ORDER BY version DESC LIMIT 1;\n IF p.id IS NULL OR p.scope_key IS DISTINCT FROM NEW.scope_key OR p.product_line_id IS DISTINCT FROM NEW.product_line_id OR NEW.study_id IS DISTINCT FROM p.study_id OR NEW.actor_user_id IS DISTINCT FROM p.deliverer_user_id OR NEW.receiver_user_id IS DISTINCT FROM p.receiver_user_id\n  OR NEW.round<>coalesce(prev.round,0)+1 OR NEW.created_at<p.created_at OR NEW.created_at<s.window_start OR NEW.created_at>=s.window_end\n  OR EXISTS(SELECT 1 FROM cehub_product.research_measurement_closures WHERE tenant_id=NEW.tenant_id AND workpack_id=NEW.workpack_id)\n  OR (prev.id IS NOT NULL AND (NEW.created_at<prev.created_at OR NOT EXISTS(SELECT 1 FROM cehub_product.research_measurement_receptions r WHERE r.tenant_id=NEW.tenant_id AND r.delivery_id=prev.id AND r.decision='returned' AND r.created_at<=NEW.created_at)))\n THEN RAISE EXCEPTION 'Delivery must append a permitted next round by the named deliverer'; END IF;\n IF sender_grant.id IS DISTINCT FROM NEW.deliverer_consent_id OR sender_grant.status IS DISTINCT FROM 'consented' OR NOT sender_grant.activity_and_aggregate_use_confirmed OR sender_grant.created_at>NEW.created_at\n  OR receiver_grant.id IS DISTINCT FROM NEW.receiver_consent_id OR receiver_grant.status IS DISTINCT FROM 'consented' OR NOT receiver_grant.activity_and_aggregate_use_confirmed OR receiver_grant.created_at>NEW.created_at\n THEN RAISE EXCEPTION 'Delivery requires current separate participant grants'; END IF;\n\n IF NEW.subject_kind='research_task' THEN\n  SELECT product_line_id,id,created_at INTO source_line,source_series,source_created FROM cehub_product.research_tasks WHERE tenant_id=NEW.tenant_id AND market_space_id=NEW.market_space_id AND id=NEW.subject_id;\n ELSIF NEW.subject_kind='scoped_work_item' THEN\n  SELECT product_line_id,id,created_at INTO source_line,source_series,source_created FROM cehub_project.scoped_work_items WHERE tenant_id=NEW.tenant_id AND market_space_id=NEW.market_space_id AND id=NEW.subject_id;\n ELSIF NEW.subject_kind='opportunity' THEN\n  SELECT product_line_id,series_id,created_at INTO source_line,source_series,source_created FROM cehub_product.opportunities WHERE tenant_id=NEW.tenant_id AND market_space_id=NEW.market_space_id AND id=NEW.subject_id;\n ELSIF NEW.subject_kind='strategy' THEN\n  SELECT product_line_id,series_id,created_at INTO source_line,source_series,source_created FROM cehub_product.product_strategies WHERE tenant_id=NEW.tenant_id AND market_space_id=NEW.market_space_id AND id=NEW.subject_id;\n ELSIF NEW.subject_kind='definition' THEN\n  SELECT product_line_id,series_id,created_at INTO source_line,source_series,source_created FROM cehub_product.product_definitions WHERE tenant_id=NEW.tenant_id AND market_space_id=NEW.market_space_id AND id=NEW.subject_id;\n END IF;\n IF source_series IS NULL OR source_series IS DISTINCT FROM NEW.subject_series_id OR source_line IS DISTINCT FROM NEW.product_line_id OR source_created>NEW.created_at\n THEN RAISE EXCEPTION 'Research workpack must reference an actual version, stable series and exact registered scope'; END IF;\n\n IF NEW.subject_kind IS DISTINCT FROM p.subject_kind OR NEW.subject_series_id IS DISTINCT FROM p.subject_series_id\n  OR jsonb_typeof(NEW.source_snapshot->'record') IS DISTINCT FROM 'object'\n  OR NEW.source_snapshot->'record'->>'id' IS DISTINCT FROM NEW.subject_id::text\n  OR NEW.source_snapshot->'record'->>'kind' IS DISTINCT FROM NEW.subject_kind\n  OR NEW.source_snapshot->'record'->>'market_space_id' IS DISTINCT FROM NEW.market_space_id::text\n  OR NEW.source_snapshot->'record'->>'product_line_id' IS DISTINCT FROM NEW.product_line_id::text\n THEN RAISE EXCEPTION 'Delivery must freeze actual content of a version in the registered series'; END IF;\n RETURN NEW;\nEND $$;\nCREATE FUNCTION cehub_product.guard_research_reception() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$\nDECLARE p cehub_product.research_measurement_workpacks;\nDECLARE s cehub_product.research_measurement_studies;\nDECLARE d cehub_product.research_measurement_deliveries;\nDECLARE receiver_grant cehub_product.research_measurement_consents;\nDECLARE sender_grant cehub_product.research_measurement_consents;\nBEGIN\n PERFORM 1 FROM cehub_product.market_spaces WHERE tenant_id=NEW.tenant_id AND id=NEW.market_space_id FOR UPDATE;\n SELECT * INTO p FROM cehub_product.research_measurement_workpacks WHERE tenant_id=NEW.tenant_id AND market_space_id=NEW.market_space_id AND id=NEW.workpack_id;\n SELECT * INTO s FROM cehub_product.research_measurement_studies WHERE tenant_id=NEW.tenant_id AND market_space_id=NEW.market_space_id AND id=p.study_id;\n SELECT * INTO d FROM cehub_product.research_measurement_deliveries WHERE tenant_id=NEW.tenant_id AND market_space_id=NEW.market_space_id AND workpack_id=NEW.workpack_id AND id=NEW.delivery_id;\n SELECT * INTO receiver_grant FROM cehub_product.research_measurement_consents WHERE tenant_id=NEW.tenant_id AND study_id=p.study_id AND participant_user_id=p.receiver_user_id ORDER BY version DESC LIMIT 1;\n SELECT * INTO sender_grant FROM cehub_product.research_measurement_consents WHERE tenant_id=NEW.tenant_id AND study_id=p.study_id AND participant_user_id=p.deliverer_user_id ORDER BY version DESC LIMIT 1;\n IF p.id IS NULL OR d.id IS NULL OR p.scope_key IS DISTINCT FROM NEW.scope_key OR p.product_line_id IS DISTINCT FROM NEW.product_line_id OR NEW.study_id IS DISTINCT FROM p.study_id OR NEW.actor_user_id IS DISTINCT FROM p.receiver_user_id OR NEW.actor_user_id=d.actor_user_id\n  OR NEW.created_at<d.created_at OR NEW.created_at<s.window_start OR NEW.created_at>=s.window_end\n  OR EXISTS(SELECT 1 FROM cehub_product.research_measurement_closures WHERE tenant_id=NEW.tenant_id AND workpack_id=NEW.workpack_id)\n  OR EXISTS(SELECT 1 FROM cehub_product.research_measurement_deliveries WHERE tenant_id=NEW.tenant_id AND workpack_id=NEW.workpack_id AND round>d.round)\n THEN RAISE EXCEPTION 'Only the independent named receiver may decide the current delivery'; END IF;\n IF receiver_grant.id IS DISTINCT FROM NEW.receiver_consent_id OR receiver_grant.id IS DISTINCT FROM d.receiver_consent_id OR receiver_grant.status IS DISTINCT FROM 'consented' OR NOT receiver_grant.activity_and_aggregate_use_confirmed OR receiver_grant.created_at>NEW.created_at\n  OR sender_grant.id IS DISTINCT FROM d.deliverer_consent_id OR sender_grant.status IS DISTINCT FROM 'consented' OR NOT sender_grant.activity_and_aggregate_use_confirmed\n THEN RAISE EXCEPTION 'Reception must retain the exact current original participant grants'; END IF;\n\n IF jsonb_typeof(NEW.source_snapshot->'record') IS DISTINCT FROM 'object'\n  OR NEW.source_snapshot->'record'->>'id' IS DISTINCT FROM d.subject_id::text\n  OR NEW.source_snapshot->'record'->>'kind' IS DISTINCT FROM d.subject_kind\n  OR (NEW.decision='accepted' AND NEW.source_snapshot->'record' IS DISTINCT FROM d.source_snapshot->'record')\n THEN RAISE EXCEPTION 'Reception must name the original delivery; changed content may only be returned'; END IF;\n RETURN NEW;\nEND $$;\nCREATE FUNCTION cehub_product.guard_research_closure() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$\nDECLARE p cehub_product.research_measurement_workpacks;\nDECLARE s cehub_product.research_measurement_studies;\nBEGIN\n PERFORM 1 FROM cehub_product.market_spaces WHERE tenant_id=NEW.tenant_id AND id=NEW.market_space_id FOR UPDATE;\n SELECT * INTO p FROM cehub_product.research_measurement_workpacks WHERE tenant_id=NEW.tenant_id AND market_space_id=NEW.market_space_id AND id=NEW.workpack_id;\n SELECT * INTO s FROM cehub_product.research_measurement_studies WHERE tenant_id=NEW.tenant_id AND market_space_id=NEW.market_space_id AND id=p.study_id;\n IF p.id IS NULL OR p.scope_key IS DISTINCT FROM NEW.scope_key OR p.product_line_id IS DISTINCT FROM NEW.product_line_id OR NEW.created_at<p.created_at OR NEW.created_at<s.window_start OR NEW.created_at>=s.window_end\n  OR EXISTS(SELECT 1 FROM cehub_product.research_measurement_receptions r WHERE r.tenant_id=NEW.tenant_id AND r.workpack_id=NEW.workpack_id AND (r.decision='accepted' OR r.created_at>NEW.created_at))\n  OR EXISTS(SELECT 1 FROM cehub_product.research_measurement_deliveries d WHERE d.tenant_id=NEW.tenant_id AND d.workpack_id=NEW.workpack_id AND d.created_at>NEW.created_at)\n THEN RAISE EXCEPTION 'Failure/cancellation must close an unaccepted current observation scope'; END IF;\n RETURN NEW;\nEND $$;\n"

TABLES = (
    "research_measurement_workpacks",
    "research_measurement_workpack_members",
    "research_measurement_deliveries",
    "research_measurement_receptions",
    "research_measurement_closures",
)


GUARD_TABLES = (
    ("research_measurement_workpacks", "workpack"),
    ("research_measurement_workpack_members", "workpack_member"),
    ("research_measurement_deliveries", "delivery"),
    ("research_measurement_receptions", "reception"),
    ("research_measurement_closures", "closure"),
)


def upgrade() -> None:
    op.execute(DDL)
    op.execute(GUARDS)
    for table, suffix in GUARD_TABLES:
        op.execute(
            f"CREATE TRIGGER guard_{table} BEFORE INSERT ON cehub_product.{table} FOR EACH ROW EXECUTE FUNCTION cehub_product.guard_research_{suffix}()"
        )
        op.execute(f"REVOKE ALL ON FUNCTION cehub_product.guard_research_{suffix}() FROM PUBLIC")
    op.execute(
        "CREATE CONSTRAINT TRIGGER guard_research_workpack_full_roster AFTER INSERT ON cehub_product.research_measurement_workpacks DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION cehub_product.guard_research_workpack_roster()"
    )
    op.execute("REVOKE ALL ON FUNCTION cehub_product.guard_research_workpack_roster() FROM PUBLIC")
    for table in TABLES:
        op.execute(
            f"CREATE TRIGGER immutable_{table} BEFORE UPDATE OR DELETE ON cehub_product.{table} FOR EACH ROW EXECUTE FUNCTION cehub_ai.protect_checkpoint_history()"
        )
        op.execute(f"REVOKE ALL ON cehub_product.{table} FROM PUBLIC")


def downgrade() -> None:
    op.execute(
        "DO $$ BEGIN IF EXISTS(SELECT 1 FROM cehub_product.research_measurement_workpacks) THEN RAISE EXCEPTION 'Retain pre-project workpack scope and all delivery/reception history'; END IF; END $$;"
    )
    for table in reversed(TABLES):
        op.execute(f"DROP TABLE cehub_product.{table}")
    for suffix in (
        "workpack_roster",
        "closure",
        "reception",
        "delivery",
        "workpack_member",
        "workpack",
    ):
        op.execute(f"DROP FUNCTION cehub_product.guard_research_{suffix}()")
